import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final byte[] buffer = new byte[1 << 16];
        private int idx = 0, size = 0;

        private int read() throws IOException {
            if (idx >= size) {
                size = System.in.read(buffer, 0, buffer.length);
                idx = 0;
                if (size <= 0) return -1;
            }
            return buffer[idx++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int T = fs.nextInt();

        int[] types = new int[N];
        for (int i = 0; i < N; i++) {
            types[i] = fs.nextInt();
        }

        ArrayList<Integer>[] lists = new ArrayList[T + 1];
        for (int i = 0; i < N; i++) {
            int price = fs.nextInt();
            int type = types[i];
            if (lists[type] == null) {
                lists[type] = new ArrayList<>();
            }
            lists[type].add(price);
        }

        for (int t = 1; t <= T; t++) {
            if (lists[t] != null) {
                Collections.sort(lists[t]);
            }
        }

        int[] ptr = new int[T + 1];
        long base = T + 1L;
        PriorityQueue<Long> pq = new PriorityQueue<>();

        for (int t = 1; t <= T; t++) {
            if (lists[t] != null && !lists[t].isEmpty()) {
                int price = lists[t].get(0);
                pq.add((long) price * base + t);
            }
        }

        int C = fs.nextInt();
        long total = 0;

        for (int i = 0; i < C; i++) {
            int u = fs.nextInt();

            if (u == 0) {
                while (!pq.isEmpty()) {
                    long key = pq.peek();
                    int type = (int) (key % base);
                    int price = (int) (key / base);

                    ArrayList<Integer> list = lists[type];
                    if (list != null && ptr[type] < list.size() && list.get(ptr[type]) == price) {
                        break;
                    }
                    pq.poll();
                }

                if (pq.isEmpty()) continue;

                long key = pq.peek();
                int type = (int) (key % base);
                int price = (int) (key / base);

                total += price;
                ptr[type]++;

                ArrayList<Integer> list = lists[type];
                if (ptr[type] < list.size()) {
                    int newPrice = list.get(ptr[type]);
                    if (newPrice != price) {
                        pq.add((long) newPrice * base + type);
                    }
                }
            } else {
                int type = u;
                ArrayList<Integer> list = lists[type];

                if (list != null && ptr[type] < list.size()) {
                    int price = list.get(ptr[type]);
                    total += price;
                    ptr[type]++;

                    if (ptr[type] < list.size()) {
                        int newPrice = list.get(ptr[type]);
                        if (newPrice != price) {
                            pq.add((long) newPrice * base + type);
                        }
                    }
                }
            }
        }

        System.out.println(total);
    }
